-- =============================================================================
-- V008: catalog — everything 3DDX sells and the order form behind each item
--
-- v2 kept: categories, sellable_items, field_types, fields, field_options,
--          item_fields, bundle_items (conventions applied: named constraints,
--          tenant_id on every tenant-owned row, standard audit/legacy columns).
-- v2 amended: articles (+ manufacturer_id, D1).
-- v3 new: item_field_rules (D3 §X5 conditional visible/required/options),
--         item_upload_requirements (D3 §X2), tooth_chart_components and
--         tooth_chart_component_conflicts (D3 §12 unified teeth chart).
--
-- Foreign keys to other schemas (clinical.implant_manufacturers,
-- workflow.workflow_states) and every tenant_id FK are added by V090
-- (migrations/fk/catalog.sql).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- catalog.field_types
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.field_types (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    code                core.entity_code NOT NULL,
    name                varchar(100) NOT NULL,
    data_type           varchar(20) NOT NULL,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_field_types PRIMARY KEY (id),
    CONSTRAINT uq_field_types__code UNIQUE (code),
    CONSTRAINT ck_field_types__data_type CHECK (data_type IN
        ('text', 'number', 'boolean', 'date', 'single_select', 'multi_select', 'file', 'tooth_chart'))
);
CREATE UNIQUE INDEX uq_field_types__legacy ON catalog.field_types
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.field_types IS 'Closed vocabulary of order-form field input types (legacy FormFieldsTypes): one row per kind of input the order form can render and the application can validate. Global, deliberately without tenant_id: a field type is a technical capability of the form engine (text box, number, date, pick-list, upload, teeth chart), identical for every tenant, and new types require application code. Seeded by V2nn; rows are never deleted while catalog.fields reference them.';
COMMENT ON COLUMN catalog.field_types.id IS 'Surrogate key. Referenced by catalog.fields.field_type_id.';
COMMENT ON COLUMN catalog.field_types.code IS 'Stable machine code of the field type (e.g. text, single_select, tooth_chart); the ETL resolves legacy FormFieldsTypes to rows by this code. System-generated seed value.';
COMMENT ON COLUMN catalog.field_types.name IS 'Human-readable name of the field type shown in catalogue administration screens.';
COMMENT ON COLUMN catalog.field_types.data_type IS 'Storage and validation shape of values of this type in orders.order_item_field_values: ''text'' = free text; ''number'' = numeric value; ''boolean'' = yes/no; ''date'' = calendar date; ''single_select'' = exactly one catalog.field_options row; ''multi_select'' = zero or more catalog.field_options rows; ''file'' = an uploaded document (docs.documents); ''tooth_chart'' = a tooth selection stored in clinical.tooth_charts / tooth_sites.';
COMMENT ON COLUMN catalog.field_types.legacy_id IS 'Source row id (legacy FormFieldsTypes.ID) when the type was migrated. NULL = created in threeddx3 (seeded).';
COMMENT ON COLUMN catalog.field_types.legacy_source IS 'Source table of the migrated row (''FormFieldsTypes''), or ''ec2:<path>'' for a JSON file. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.field_types.legacy_key IS 'Composite source key when one legacy id is not enough to identify the source row. NULL = legacy_id alone identifies it, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.field_types.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.field_types.updated_at IS 'UTC instant of the last update, maintained by trg_field_types__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.field_types.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.field_types.updated_by_user_id IS 'iam.users id of the user who last updated the row (set by the touch trigger from app.user_id). No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_field_types ON catalog.field_types IS 'One row per field type.';
COMMENT ON CONSTRAINT uq_field_types__code ON catalog.field_types IS 'A field type code identifies exactly one type across the whole platform; the ETL and seeds look types up by code.';
COMMENT ON CONSTRAINT ck_field_types__data_type ON catalog.field_types IS 'Only the value shapes the form engine and orders.order_item_field_values can store are allowed.';
COMMENT ON INDEX catalog.uq_field_types__legacy IS 'Every migrated row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_field_types__touch_updated_at BEFORE UPDATE ON catalog.field_types
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_field_types__touch_updated_at ON catalog.field_types IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.categories
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.categories (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    parent_id           bigint,
    code                core.entity_code NOT NULL,
    name                varchar(150) NOT NULL,
    description         text,
    sort_order          integer NOT NULL DEFAULT 0,
    is_active           boolean NOT NULL DEFAULT true,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_categories PRIMARY KEY (id),
    CONSTRAINT uq_categories__uuid UNIQUE (uuid),
    CONSTRAINT uq_categories__tenant_id__code UNIQUE (tenant_id, code),
    CONSTRAINT ck_categories__not_own_parent CHECK (parent_id IS NULL OR parent_id <> id),
    CONSTRAINT fk_categories__parent_id FOREIGN KEY (parent_id)
        REFERENCES catalog.categories (id) ON DELETE SET NULL ON UPDATE NO ACTION
);
CREATE INDEX ix_categories__parent_id ON catalog.categories (parent_id) WHERE parent_id IS NOT NULL;
CREATE UNIQUE INDEX uq_categories__legacy ON catalog.categories
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.categories IS 'Order types / service families that group sellable items (legacy OrderTypes and IsmileOrderType): surgical guide, treatment plan, report, restoration, appliance, software, iSmile, GFMR, FMP, misc, other. One row = one category of one tenant, optionally nested under a parent. Owned by the catalog module; referenced by catalog.sellable_items, pricing.formulas and pricing.rules. Retired by is_active = false, never deleted while referenced.';
COMMENT ON COLUMN catalog.categories.id IS 'Surrogate key. Referenced by sellable items, pricing formulas and pricing rules.';
COMMENT ON COLUMN catalog.categories.uuid IS 'Public identifier used by the API instead of the numeric id. System-generated.';
COMMENT ON COLUMN catalog.categories.tenant_id IS 'Owning tenant (core.tenants; FK added by V090). Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.categories.parent_id IS 'Parent category for nested grouping (e.g. iSmile order types under iSmile). NULL = top-level category.';
COMMENT ON COLUMN catalog.categories.code IS 'Stable machine code, unique per tenant (e.g. surgical_guide, restoration). Part of every sellable item code of the category (v2 defect 48). Migrated from OrderTypes.name via slug, or seeded.';
COMMENT ON COLUMN catalog.categories.name IS 'Display name of the category. Migrated from OrderTypes.name / IsmileOrderType.name, or user input.';
COMMENT ON COLUMN catalog.categories.description IS 'Free-text description shown to staff in catalogue administration. NULL = no description written.';
COMMENT ON COLUMN catalog.categories.sort_order IS 'Display order among siblings, ascending. User input; 0 by default.';
COMMENT ON COLUMN catalog.categories.is_active IS 'False = retired: not offered for new orders, history intact.';
COMMENT ON COLUMN catalog.categories.legacy_id IS 'Source row id (OrderTypes.ID or IsmileOrderType.id). NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.categories.legacy_source IS 'Source table of the migrated row (''OrderTypes'', ''IsmileOrderType''), or ''ec2:<path>''. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.categories.legacy_key IS 'Composite source key when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.categories.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.categories.updated_at IS 'UTC instant of the last update, maintained by trg_categories__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.categories.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.categories.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_categories ON catalog.categories IS 'One row per category.';
COMMENT ON CONSTRAINT uq_categories__uuid ON catalog.categories IS 'The public identifier is unique.';
COMMENT ON CONSTRAINT uq_categories__tenant_id__code ON catalog.categories IS 'A category code is unique within a tenant; the ETL upserts categories on (tenant_id, code).';
COMMENT ON CONSTRAINT ck_categories__not_own_parent ON catalog.categories IS 'A category cannot be its own parent.';
COMMENT ON CONSTRAINT fk_categories__parent_id ON catalog.categories IS 'Nested categories point to their parent; removing a parent makes its children top-level (optional link).';
COMMENT ON INDEX catalog.ix_categories__parent_id IS 'Lists the children of a category and serves the FK check when a parent is deleted.';
COMMENT ON INDEX catalog.uq_categories__legacy IS 'Every migrated row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_categories__touch_updated_at BEFORE UPDATE ON catalog.categories
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_categories__touch_updated_at ON catalog.categories IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.sellable_items
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.sellable_items (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    category_id         bigint,
    item_kind           catalog.item_kind NOT NULL,
    fulfilment_kind     catalog.fulfilment_kind NOT NULL DEFAULT 'production',
    code                core.entity_code NOT NULL,
    name                varchar(200) NOT NULL,
    description         text,
    sku                 varchar(80),
    is_digital          boolean NOT NULL DEFAULT false,
    requires_shipping   boolean NOT NULL DEFAULT false,
    requires_patient    boolean NOT NULL DEFAULT true,
    pricing_method      varchar(30) NOT NULL DEFAULT 'fixed',
    default_lead_days   smallint,
    workflow_code       core.entity_code,
    state               core.lifecycle_state NOT NULL DEFAULT 'active',
    sort_order          integer NOT NULL DEFAULT 0,
    metadata            jsonb NOT NULL DEFAULT '{}'::jsonb,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_sellable_items PRIMARY KEY (id),
    CONSTRAINT uq_sellable_items__uuid UNIQUE (uuid),
    CONSTRAINT uq_sellable_items__tenant_id__code UNIQUE (tenant_id, code),
    CONSTRAINT ck_sellable_items__pricing_method CHECK (pricing_method IN
        ('fixed', 'per_field', 'per_unit', 'tiered', 'quote', 'free', 'formula')),
    CONSTRAINT ck_sellable_items__default_lead_days_range CHECK (default_lead_days IS NULL OR default_lead_days >= 0),
    CONSTRAINT ck_sellable_items__metadata_object CHECK (jsonb_typeof(metadata) = 'object'),
    CONSTRAINT fk_sellable_items__category_id FOREIGN KEY (category_id)
        REFERENCES catalog.categories (id) ON DELETE RESTRICT ON UPDATE NO ACTION
);
CREATE INDEX ix_sellable_items__category_id ON catalog.sellable_items (category_id) WHERE category_id IS NOT NULL;
CREATE UNIQUE INDEX uq_sellable_items__legacy ON catalog.sellable_items
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.sellable_items IS 'Everything 3DDX sells: a service (design, planning, production per case), product (printer, resin, kit), licence, rental or bundle. One row = one sellable item of one tenant. Legacy Services (one row per service and order type: a temporary and a final crown, or a crown on a restoration vs an appliance order, are different services — v2 defect 48), product_details (3D printers and accessories) and the price dimensions of the wide UserAcounts price book migrate here. Owned by the catalog module; referenced by order items, shopping carts, bundles, pricing lists, formulas, tiers and rules. Lifecycle by state (never deleted once ordered).';
COMMENT ON COLUMN catalog.sellable_items.id IS 'Surrogate key. Referenced by orders.order_items, pricing.price_list_items and the other catalog/pricing tables.';
COMMENT ON COLUMN catalog.sellable_items.uuid IS 'Public identifier used by the API instead of the numeric id. System-generated.';
COMMENT ON COLUMN catalog.sellable_items.tenant_id IS 'Owning tenant (core.tenants; FK added by V090). Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.sellable_items.category_id IS 'Category (order type / service family) the item belongs to. Migrated from Services.orderTypeID. NULL = uncategorised (products from the shopping cart and price dimensions of the wide price book).';
COMMENT ON COLUMN catalog.sellable_items.item_kind IS 'What the item is (catalog.item_kind): service, product, license, rental or bundle.';
COMMENT ON COLUMN catalog.sellable_items.fulfilment_kind IS 'How the item is delivered once ordered (catalog.fulfilment_kind): production, inventory, licensing, rental, manual or none.';
COMMENT ON COLUMN catalog.sellable_items.code IS 'Stable machine code, unique per tenant. For migrated services it is the service name plus the category code (e.g. crown_restoration vs crown_appliance) so services that share a name but differ by order type stay distinct (v2 defect 48). Formula terms find their rates by this code (pricing.formula_terms.rate_item_code).';
COMMENT ON COLUMN catalog.sellable_items.name IS 'Display name of the item. Migrated from Services.name / product_details.product_type, or user input.';
COMMENT ON COLUMN catalog.sellable_items.description IS 'Long description shown to clients and staff. NULL = no description written.';
COMMENT ON COLUMN catalog.sellable_items.sku IS 'Stock-keeping unit for physical products and accessories. NULL = not a stocked product (services, licences).';
COMMENT ON COLUMN catalog.sellable_items.is_digital IS 'True = delivered as files only (digital design service); false = involves a physical deliverable.';
COMMENT ON COLUMN catalog.sellable_items.requires_shipping IS 'True = an order for this item creates a shipment.';
COMMENT ON COLUMN catalog.sellable_items.requires_patient IS 'True = an order for this item must name a patient (clinical services); false for printers, resins and licences.';
COMMENT ON COLUMN catalog.sellable_items.pricing_method IS 'How the price is obtained: ''fixed'' = one price per price list; ''per_field'' = item price plus the price of each priced field selected; ''per_unit'' = price times quantity; ''tiered'' = pricing.tiers by quantity; ''quote'' = priced manually per order; ''free'' = no charge; ''formula'' = computed by pricing.formulas (classic surgical-guide engine). Migrated from Services.pricingMethodID (legacy PricingMethods).';
COMMENT ON COLUMN catalog.sellable_items.default_lead_days IS 'Default production lead time in calendar days used to propose a due date. NULL = no default; the workflow SLA decides.';
COMMENT ON COLUMN catalog.sellable_items.workflow_code IS 'Code of the workflow.workflow_definitions row that drives this item once ordered (legacy OrdersFlow keyed on order type and serviceID). NULL = the workflow is chosen from the category and the legacy service dimension at order time.';
COMMENT ON COLUMN catalog.sellable_items.state IS 'Lifecycle (core.lifecycle_state): ''draft'' = being prepared, not orderable; ''active'' = orderable; ''suspended'' = temporarily not orderable; ''deprecated'' = no new orders, history intact (legacy Services.isDeprecated, e.g. Full Arch Restoration Final); ''archived'' = history only.';
COMMENT ON COLUMN catalog.sellable_items.sort_order IS 'Display order in service selection lists, ascending.';
COMMENT ON COLUMN catalog.sellable_items.metadata IS 'Display-only attributes that are never filtered or reported on (icons, marketing copy keys). JSON object.';
COMMENT ON COLUMN catalog.sellable_items.legacy_id IS 'Source row id (Services.ID, product_details.product_ID). NULL = created in threeddx3 or derived from a column of the wide UserAcounts price book.';
COMMENT ON COLUMN catalog.sellable_items.legacy_source IS 'Source of the migrated row (''Services'', ''product_details'', ''UserAcounts'' for price dimensions), or ''ec2:<path>''. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.sellable_items.legacy_key IS 'Composite source key when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.sellable_items.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.sellable_items.updated_at IS 'UTC instant of the last update, maintained by trg_sellable_items__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.sellable_items.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.sellable_items.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_sellable_items ON catalog.sellable_items IS 'One row per sellable item.';
COMMENT ON CONSTRAINT uq_sellable_items__uuid ON catalog.sellable_items IS 'The public identifier is unique.';
COMMENT ON CONSTRAINT uq_sellable_items__tenant_id__code ON catalog.sellable_items IS 'An item code is unique within a tenant; because the code includes the order type, two services with the same name in different order types do not collapse into one (v2 defect 48: 25 services became 20).';
COMMENT ON CONSTRAINT ck_sellable_items__pricing_method ON catalog.sellable_items IS 'Only pricing methods the pricing engine implements are allowed.';
COMMENT ON CONSTRAINT ck_sellable_items__default_lead_days_range ON catalog.sellable_items IS 'A lead time cannot be negative.';
COMMENT ON CONSTRAINT ck_sellable_items__metadata_object ON catalog.sellable_items IS 'metadata is always a JSON object, never an array or scalar.';
COMMENT ON CONSTRAINT fk_sellable_items__category_id ON catalog.sellable_items IS 'An item belongs to an existing category; a category with items cannot be deleted (retire it with is_active = false).';
COMMENT ON INDEX catalog.ix_sellable_items__category_id IS 'Lists the items of a category (service selection screens) and serves the FK check when a category is deleted.';
COMMENT ON INDEX catalog.uq_sellable_items__legacy IS 'Every migrated row is traceable to one source row and cannot be loaded twice. Note: ETL stage 00 upserts services with ON CONFLICT (legacy_source, legacy_id); it must name this index''s columns and predicate instead.';

CREATE TRIGGER trg_sellable_items__touch_updated_at BEFORE UPDATE ON catalog.sellable_items
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_sellable_items__touch_updated_at ON catalog.sellable_items IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.bundle_items
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.bundle_items (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    bundle_item_id      bigint NOT NULL,
    child_item_id       bigint NOT NULL,
    quantity            numeric(10,3) NOT NULL DEFAULT 1,
    is_optional         boolean NOT NULL DEFAULT false,
    sort_order          integer NOT NULL DEFAULT 0,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_bundle_items PRIMARY KEY (id),
    CONSTRAINT uq_bundle_items__bundle_item_id__child_item_id UNIQUE (bundle_item_id, child_item_id),
    CONSTRAINT ck_bundle_items__not_self CHECK (bundle_item_id <> child_item_id),
    CONSTRAINT ck_bundle_items__quantity_positive CHECK (quantity > 0),
    CONSTRAINT fk_bundle_items__bundle_item_id FOREIGN KEY (bundle_item_id)
        REFERENCES catalog.sellable_items (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT fk_bundle_items__child_item_id FOREIGN KEY (child_item_id)
        REFERENCES catalog.sellable_items (id) ON DELETE RESTRICT ON UPDATE NO ACTION
);
CREATE INDEX ix_bundle_items__child_item_id ON catalog.bundle_items (child_item_id);
CREATE UNIQUE INDEX uq_bundle_items__legacy ON catalog.bundle_items
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.bundle_items IS 'Composition of a bundle sellable item (item_kind = bundle), e.g. a prepaid package or a GFMR programme. One row = one component item and its quantity inside one bundle. Configuration child of catalog.sellable_items: removed with the bundle, edited in place.';
COMMENT ON COLUMN catalog.bundle_items.id IS 'Surrogate key of the bundle component row; not referenced elsewhere.';
COMMENT ON COLUMN catalog.bundle_items.tenant_id IS 'Owning tenant (core.tenants; FK added by V090); always the tenant of the bundle. Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.bundle_items.bundle_item_id IS 'The bundle (catalog.sellable_items with item_kind = bundle) this row belongs to.';
COMMENT ON COLUMN catalog.bundle_items.child_item_id IS 'The sellable item included in the bundle.';
COMMENT ON COLUMN catalog.bundle_items.quantity IS 'How many units of the child item the bundle includes. Positive; three decimals for fractional units (e.g. resin litres).';
COMMENT ON COLUMN catalog.bundle_items.is_optional IS 'True = the client may leave this component out when ordering the bundle.';
COMMENT ON COLUMN catalog.bundle_items.sort_order IS 'Display order of components within the bundle, ascending.';
COMMENT ON COLUMN catalog.bundle_items.legacy_id IS 'Source row id when migrated. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.bundle_items.legacy_source IS 'Source table of the migrated row, or ''ec2:<path>''. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.bundle_items.legacy_key IS 'Composite source key when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.bundle_items.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.bundle_items.updated_at IS 'UTC instant of the last update, maintained by trg_bundle_items__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.bundle_items.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.bundle_items.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_bundle_items ON catalog.bundle_items IS 'One row per bundle component.';
COMMENT ON CONSTRAINT uq_bundle_items__bundle_item_id__child_item_id ON catalog.bundle_items IS 'An item appears at most once in a bundle; more units are expressed by quantity.';
COMMENT ON CONSTRAINT ck_bundle_items__not_self ON catalog.bundle_items IS 'A bundle cannot contain itself.';
COMMENT ON CONSTRAINT ck_bundle_items__quantity_positive ON catalog.bundle_items IS 'A bundle component has a positive quantity.';
COMMENT ON CONSTRAINT fk_bundle_items__bundle_item_id ON catalog.bundle_items IS 'Components belong to their bundle and are removed with it (configuration child, no financial content).';
COMMENT ON CONSTRAINT fk_bundle_items__child_item_id ON catalog.bundle_items IS 'An item that is part of a bundle cannot be deleted while the bundle lists it.';
COMMENT ON INDEX catalog.ix_bundle_items__child_item_id IS 'Finds the bundles that contain an item and serves the FK check when an item is deleted.';
COMMENT ON INDEX catalog.uq_bundle_items__legacy IS 'Every migrated row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_bundle_items__touch_updated_at BEFORE UPDATE ON catalog.bundle_items
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_bundle_items__touch_updated_at ON catalog.bundle_items IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.fields
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.fields (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    field_type_id       bigint NOT NULL,
    code                core.entity_code NOT NULL,
    label               varchar(200) NOT NULL,
    help_text           text,
    is_priced           boolean NOT NULL DEFAULT false,
    unit                varchar(30),
    validation          jsonb NOT NULL DEFAULT '{}'::jsonb,
    is_active           boolean NOT NULL DEFAULT true,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_fields PRIMARY KEY (id),
    CONSTRAINT uq_fields__uuid UNIQUE (uuid),
    CONSTRAINT uq_fields__tenant_id__code UNIQUE (tenant_id, code),
    CONSTRAINT ck_fields__validation_object CHECK (jsonb_typeof(validation) = 'object'),
    CONSTRAINT fk_fields__field_type_id FOREIGN KEY (field_type_id)
        REFERENCES catalog.field_types (id) ON DELETE RESTRICT ON UPDATE NO ACTION
);
CREATE INDEX ix_fields__field_type_id ON catalog.fields (field_type_id);
CREATE UNIQUE INDEX uq_fields__legacy ON catalog.fields
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.fields IS 'Order-form questions (legacy FormFields, product_property): one row = one field definition of one tenant, reusable across sellable items through catalog.item_fields. Answers are stored per order item in orders.order_item_field_values; priced fields carry rates in pricing.price_list_items. Fields are retired with is_active = false so old cases keep their answers (Restorative Services Forms Update: adds, removes and renames are seed changes).';
COMMENT ON COLUMN catalog.fields.id IS 'Surrogate key. Referenced by item_fields, field_options, order item field values and price list items.';
COMMENT ON COLUMN catalog.fields.uuid IS 'Public identifier used by the API instead of the numeric id. System-generated.';
COMMENT ON COLUMN catalog.fields.tenant_id IS 'Owning tenant (core.tenants; FK added by V090). Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.fields.field_type_id IS 'Input type of the field (catalog.field_types). Migrated from FormFields.typeID.';
COMMENT ON COLUMN catalog.fields.code IS 'Stable machine code, unique per tenant (e.g. shade_system, screw_type). Conditions in catalog.item_field_rules and catalog.item_upload_requirements refer to fields by this code.';
COMMENT ON COLUMN catalog.fields.label IS 'Question text shown on the order form. Migrated from FormFields.name, or user input.';
COMMENT ON COLUMN catalog.fields.help_text IS 'Hint shown under the field (e.g. "Pricing excluding Components"). NULL = no hint.';
COMMENT ON COLUMN catalog.fields.is_priced IS 'True when the field carries its own price (legacy PricedFields); its rates live in pricing.price_list_items.field_id.';
COMMENT ON COLUMN catalog.fields.unit IS 'Unit of a numeric answer (mm, degrees, units). NULL = the answer has no unit.';
COMMENT ON COLUMN catalog.fields.validation IS 'Static validation of a single answer (min, max, max_length, pattern). Conditional visibility, requiredness and option filtering are NOT stored here but in catalog.item_field_rules. JSON object.';
COMMENT ON COLUMN catalog.fields.is_active IS 'False = retired: no longer shown on new orders; answers on old cases remain.';
COMMENT ON COLUMN catalog.fields.legacy_id IS 'Source row id (FormFields.ID, product_property.product_property_ID). NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.fields.legacy_source IS 'Source table of the migrated row (''FormFields'', ''product_property''), or ''ec2:<path>''. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.fields.legacy_key IS 'Composite source key when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.fields.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.fields.updated_at IS 'UTC instant of the last update, maintained by trg_fields__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.fields.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.fields.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_fields ON catalog.fields IS 'One row per field definition.';
COMMENT ON CONSTRAINT uq_fields__uuid ON catalog.fields IS 'The public identifier is unique.';
COMMENT ON CONSTRAINT uq_fields__tenant_id__code ON catalog.fields IS 'A field code is unique within a tenant; rules and the ETL refer to fields by code.';
COMMENT ON CONSTRAINT ck_fields__validation_object ON catalog.fields IS 'validation is always a JSON object.';
COMMENT ON CONSTRAINT fk_fields__field_type_id ON catalog.fields IS 'A field has an existing input type; a type in use cannot be deleted.';
COMMENT ON INDEX catalog.ix_fields__field_type_id IS 'Serves the FK check when a field type is deleted and lists fields by type in administration.';
COMMENT ON INDEX catalog.uq_fields__legacy IS 'Every migrated row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_fields__touch_updated_at BEFORE UPDATE ON catalog.fields
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_fields__touch_updated_at ON catalog.fields IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.field_options
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.field_options (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    field_id            bigint NOT NULL,
    code                varchar(100) NOT NULL,
    label               varchar(200) NOT NULL,
    sort_order          integer NOT NULL DEFAULT 0,
    is_active           boolean NOT NULL DEFAULT true,
    metadata            jsonb NOT NULL DEFAULT '{}'::jsonb,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_field_options PRIMARY KEY (id),
    CONSTRAINT uq_field_options__field_id__code UNIQUE (field_id, code),
    CONSTRAINT ck_field_options__metadata_object CHECK (jsonb_typeof(metadata) = 'object'),
    CONSTRAINT fk_field_options__field_id FOREIGN KEY (field_id)
        REFERENCES catalog.fields (id) ON DELETE CASCADE ON UPDATE NO ACTION
);
CREATE UNIQUE INDEX uq_field_options__legacy ON catalog.field_options
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.field_options IS 'Allowed answers of a select field (legacy FormFields option lists and the JSON pick-lists on EC2): one row = one option of one field. Configuration child of catalog.fields. Options are retired with is_active = false (or renamed in place, e.g. Optisplint -> Shining 3D Elite) so orders that chose them keep a valid reference in orders.order_item_field_values.';
COMMENT ON COLUMN catalog.field_options.id IS 'Surrogate key. Referenced by orders.order_item_field_values.';
COMMENT ON COLUMN catalog.field_options.tenant_id IS 'Owning tenant (core.tenants; FK added by V090); always the tenant of the field. Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.field_options.field_id IS 'The select field this option belongs to.';
COMMENT ON COLUMN catalog.field_options.code IS 'Stable code of the option within its field; catalog.item_field_rules.option_codes and rule conditions refer to options by this code. Free-form (legacy option values are not always slugs), up to 100 characters.';
COMMENT ON COLUMN catalog.field_options.label IS 'Text shown for the option on the order form.';
COMMENT ON COLUMN catalog.field_options.sort_order IS 'Display order within the field, ascending.';
COMMENT ON COLUMN catalog.field_options.is_active IS 'False = no longer offered on new orders; existing answers remain valid.';
COMMENT ON COLUMN catalog.field_options.metadata IS 'Display-only attributes of the option (colour swatch, image key). Never filtered or reported on. JSON object.';
COMMENT ON COLUMN catalog.field_options.legacy_id IS 'Source row id of the option when migrated. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.field_options.legacy_source IS 'Source table of the migrated row, or ''ec2:<path>'' for a JSON pick-list. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.field_options.legacy_key IS 'Composite source key (e.g. JSON array position) when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.field_options.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.field_options.updated_at IS 'UTC instant of the last update, maintained by trg_field_options__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.field_options.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.field_options.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_field_options ON catalog.field_options IS 'One row per option.';
COMMENT ON CONSTRAINT uq_field_options__field_id__code ON catalog.field_options IS 'An option code is unique within its field; the ETL upserts options on (field_id, code).';
COMMENT ON CONSTRAINT ck_field_options__metadata_object ON catalog.field_options IS 'metadata is always a JSON object.';
COMMENT ON CONSTRAINT fk_field_options__field_id ON catalog.field_options IS 'Options belong to their field and are removed with it (configuration child). Options already chosen on orders are protected by the RESTRICT FK from orders.order_item_field_values.';
COMMENT ON INDEX catalog.uq_field_options__legacy IS 'Every migrated row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_field_options__touch_updated_at BEFORE UPDATE ON catalog.field_options
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_field_options__touch_updated_at ON catalog.field_options IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.item_fields
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.item_fields (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    item_id             bigint NOT NULL,
    field_id            bigint NOT NULL,
    is_required         boolean NOT NULL DEFAULT false,
    sort_order          integer NOT NULL DEFAULT 0,
    section             varchar(100),
    default_value       text,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_item_fields PRIMARY KEY (id),
    CONSTRAINT uq_item_fields__item_id__field_id UNIQUE (item_id, field_id),
    CONSTRAINT fk_item_fields__item_id FOREIGN KEY (item_id)
        REFERENCES catalog.sellable_items (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT fk_item_fields__field_id FOREIGN KEY (field_id)
        REFERENCES catalog.fields (id) ON DELETE CASCADE ON UPDATE NO ACTION
);
CREATE INDEX ix_item_fields__field_id ON catalog.item_fields (field_id);
CREATE UNIQUE INDEX uq_item_fields__legacy ON catalog.item_fields
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.item_fields IS 'Which order-form fields a sellable item asks for (legacy ServicesFields, 314 rows): one row = one field placed on one item''s form, with its static requiredness, position and default. Conditional behaviour (visible / required / option subset depending on other answers or Digital vs Physical) is layered on top by catalog.item_field_rules. Configuration child of the item and the field.';
COMMENT ON COLUMN catalog.item_fields.id IS 'Surrogate key. Referenced by catalog.item_field_rules.';
COMMENT ON COLUMN catalog.item_fields.tenant_id IS 'Owning tenant (core.tenants; FK added by V090); always the tenant of the item. Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.item_fields.item_id IS 'The sellable item whose form contains the field. Migrated from ServicesFields.serviceID.';
COMMENT ON COLUMN catalog.item_fields.field_id IS 'The field placed on the form. Migrated from ServicesFields.fieldID.';
COMMENT ON COLUMN catalog.item_fields.is_required IS 'Static requiredness: true = must be answered unless a ''required'' rule in catalog.item_field_rules makes it conditional. Phase-2 restorative changes (required <-> optional) are seed updates of this flag.';
COMMENT ON COLUMN catalog.item_fields.sort_order IS 'Position of the field on the item''s form, ascending.';
COMMENT ON COLUMN catalog.item_fields.section IS 'Form section heading the field appears under (e.g. Shade Information). NULL = the form''s default section.';
COMMENT ON COLUMN catalog.item_fields.default_value IS 'Pre-filled answer as text (option code for select fields). NULL = no default; the field starts empty.';
COMMENT ON COLUMN catalog.item_fields.legacy_id IS 'Source row id (ServicesFields.ID). NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.item_fields.legacy_source IS 'Source table of the migrated row (''ServicesFields''), or ''ec2:<path>''. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.item_fields.legacy_key IS 'Composite source key when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.item_fields.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.item_fields.updated_at IS 'UTC instant of the last update, maintained by trg_item_fields__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.item_fields.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.item_fields.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_item_fields ON catalog.item_fields IS 'One row per field placement.';
COMMENT ON CONSTRAINT uq_item_fields__item_id__field_id ON catalog.item_fields IS 'A field appears at most once on an item''s form; the ETL inserts with ON CONFLICT (item_id, field_id).';
COMMENT ON CONSTRAINT fk_item_fields__item_id ON catalog.item_fields IS 'Placements belong to the item and are removed with it (configuration child).';
COMMENT ON CONSTRAINT fk_item_fields__field_id ON catalog.item_fields IS 'Placements of a field are removed with the field (configuration link, no history).';
COMMENT ON INDEX catalog.ix_item_fields__field_id IS 'Finds every item whose form uses a field (impact of a field change) and serves the FK check when a field is deleted.';
COMMENT ON INDEX catalog.uq_item_fields__legacy IS 'Every migrated row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_item_fields__touch_updated_at BEFORE UPDATE ON catalog.item_fields
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_item_fields__touch_updated_at ON catalog.item_fields IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.item_field_rules  (v3 new, D3 §X5)
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.item_field_rules (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    item_field_id       bigint NOT NULL,
    rule_kind           varchar(20) NOT NULL,
    condition           jsonb NOT NULL DEFAULT '{}'::jsonb,
    option_codes        varchar(100)[],
    sort_order          integer NOT NULL DEFAULT 0,
    is_active           boolean NOT NULL DEFAULT true,
    notes               text,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_item_field_rules PRIMARY KEY (id),
    CONSTRAINT ck_item_field_rules__rule_kind CHECK (rule_kind IN ('visible', 'required', 'options')),
    CONSTRAINT ck_item_field_rules__condition_object CHECK (jsonb_typeof(condition) = 'object'),
    CONSTRAINT ck_item_field_rules__options_only_for_options CHECK ((rule_kind = 'options') = (option_codes IS NOT NULL)),
    CONSTRAINT ck_item_field_rules__option_codes_valid CHECK (
        option_codes IS NULL
        OR (cardinality(option_codes) >= 1 AND array_position(option_codes, NULL) IS NULL)),
    CONSTRAINT fk_item_field_rules__item_field_id FOREIGN KEY (item_field_id)
        REFERENCES catalog.item_fields (id) ON DELETE CASCADE ON UPDATE NO ACTION
);
CREATE INDEX ix_item_field_rules__item_field_id ON catalog.item_field_rules (item_field_id);
CREATE UNIQUE INDEX uq_item_field_rules__legacy ON catalog.item_field_rules
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.item_field_rules IS 'Conditional order-form rules (D3 §X5): a field on an item''s form becomes visible, required, or limited to a subset of its options depending on other answers or on order-line attributes such as Digital vs Physical. Examples: Screw Type required only when Kind of Implant = OEM; Gingiva Shade options filtered by Gingiva Shade System (Vita / Ivoclar / Other -> text required); Abutment options filtered by Retention. One row = one rule on one item_fields placement. Evaluation (V100, server side, re-run on submit): for ''visible'' and ''required'' the field is visible / required when any active rule of that kind holds, and falls back to always-visible / item_fields.is_required when it has no active rule of that kind; for ''options'' the first active rule that holds (by sort_order) limits the options, and with none holding all active options are offered. Configuration child of catalog.item_fields.';
COMMENT ON COLUMN catalog.item_field_rules.id IS 'Surrogate key of the conditional form rule; not referenced elsewhere.';
COMMENT ON COLUMN catalog.item_field_rules.tenant_id IS 'Owning tenant (core.tenants; FK added by V090); always the tenant of the item field. Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.item_field_rules.item_field_id IS 'The field placement (field on one sellable item''s form) the rule controls.';
COMMENT ON COLUMN catalog.item_field_rules.rule_kind IS 'What the rule controls: ''visible'' = the field is shown only while the condition holds; ''required'' = the field must be answered while the condition holds; ''options'' = while the condition holds only option_codes are offered.';
COMMENT ON COLUMN catalog.item_field_rules.condition IS 'When the rule applies, as a JSON object over other answers on the same form. Shape: a leaf {"field": "<catalog.fields.code>", "op": "<op>", "value": <scalar>} or {"field": ..., "op": "in"|"not_in", "values": [<scalar>, ...]}, where op is one of eq, ne, in, not_in, is_set, is_not_set, gt, gte, lt, lte and a select answer is compared by option code; a leaf may name an order-line attribute instead of a field: {"attribute": "is_digital", "op": "eq", "value": true}; combinators {"all": [<cond>, ...]}, {"any": [<cond>, ...]}, {"not": <cond>}. {} = always holds. Validated by the V100 evaluator; only the object type is checked here.';
COMMENT ON COLUMN catalog.item_field_rules.option_codes IS 'For rule_kind = ''options'': the codes (catalog.field_options.code of the controlled field) offered while the condition holds. Codes rather than ids so seeds are portable between environments; membership is validated by V100. NULL = not an options rule.';
COMMENT ON COLUMN catalog.item_field_rules.sort_order IS 'Evaluation order among ''options'' rules of the same field placement, ascending; the first that holds wins.';
COMMENT ON COLUMN catalog.item_field_rules.is_active IS 'False = rule switched off without deleting it (kept for review of which rule applied to old cases).';
COMMENT ON COLUMN catalog.item_field_rules.notes IS 'Why the rule exists, e.g. the requirement document and user story it implements. NULL = no note.';
COMMENT ON COLUMN catalog.item_field_rules.legacy_id IS 'Source row id when loaded from a legacy source. NULL = created in threeddx3 (seeded or configured).';
COMMENT ON COLUMN catalog.item_field_rules.legacy_source IS 'Source of a loaded row, e.g. ''ec2:<path>'' for a JSON form definition. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.item_field_rules.legacy_key IS 'Composite source key when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.item_field_rules.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.item_field_rules.updated_at IS 'UTC instant of the last update, maintained by trg_item_field_rules__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.item_field_rules.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.item_field_rules.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_item_field_rules ON catalog.item_field_rules IS 'One row per rule.';
COMMENT ON CONSTRAINT ck_item_field_rules__rule_kind ON catalog.item_field_rules IS 'A rule controls visibility, requiredness or the option subset, nothing else.';
COMMENT ON CONSTRAINT ck_item_field_rules__condition_object ON catalog.item_field_rules IS 'A condition is a JSON object (leaf or combinator, {} = always).';
COMMENT ON CONSTRAINT ck_item_field_rules__options_only_for_options ON catalog.item_field_rules IS 'An option subset is given exactly when the rule is an ''options'' rule.';
COMMENT ON CONSTRAINT ck_item_field_rules__option_codes_valid ON catalog.item_field_rules IS 'An option subset names at least one option and contains no NULL code.';
COMMENT ON CONSTRAINT fk_item_field_rules__item_field_id ON catalog.item_field_rules IS 'Rules belong to the field placement and are removed with it (configuration child).';
COMMENT ON INDEX catalog.ix_item_field_rules__item_field_id IS 'Loads the rules of a form''s fields when the form is rendered or validated; serves the FK check.';
COMMENT ON INDEX catalog.uq_item_field_rules__legacy IS 'Every loaded row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_item_field_rules__touch_updated_at BEFORE UPDATE ON catalog.item_field_rules
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_item_field_rules__touch_updated_at ON catalog.item_field_rules IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.item_upload_requirements  (v3 new, D3 §X2)
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.item_upload_requirements (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    sellable_item_id    bigint,
    workflow_state_id   bigint,
    purpose_code        core.entity_code NOT NULL,
    is_required         boolean NOT NULL DEFAULT true,
    allowed_extensions  varchar(20)[] NOT NULL DEFAULT '{}',
    max_size_bytes      bigint NOT NULL,
    max_file_count      smallint NOT NULL DEFAULT 1,
    condition           jsonb NOT NULL DEFAULT '{}'::jsonb,
    sort_order          integer NOT NULL DEFAULT 0,
    is_active           boolean NOT NULL DEFAULT true,
    notes               text,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_item_upload_requirements PRIMARY KEY (id),
    CONSTRAINT ck_item_upload_requirements__scope CHECK (num_nonnulls(sellable_item_id, workflow_state_id) >= 1),
    CONSTRAINT ck_item_upload_requirements__max_size_positive CHECK (max_size_bytes > 0),
    CONSTRAINT ck_item_upload_requirements__max_file_count_positive CHECK (max_file_count > 0),
    CONSTRAINT ck_item_upload_requirements__extensions_format CHECK (
        array_position(allowed_extensions, NULL) IS NULL
        AND array_to_string(allowed_extensions, '|') ~ '^(\.[a-z0-9]+(\.[a-z0-9]+)*(\|\.[a-z0-9]+(\.[a-z0-9]+)*)*)?$'),
    CONSTRAINT ck_item_upload_requirements__condition_object CHECK (jsonb_typeof(condition) = 'object'),
    CONSTRAINT fk_item_upload_requirements__sellable_item_id FOREIGN KEY (sellable_item_id)
        REFERENCES catalog.sellable_items (id) ON DELETE CASCADE ON UPDATE NO ACTION
);
CREATE INDEX ix_item_upload_requirements__sellable_item_id ON catalog.item_upload_requirements (sellable_item_id)
    WHERE sellable_item_id IS NOT NULL;
CREATE INDEX ix_item_upload_requirements__workflow_state_id ON catalog.item_upload_requirements (workflow_state_id)
    WHERE workflow_state_id IS NOT NULL;
CREATE UNIQUE INDEX uq_item_upload_requirements__legacy ON catalog.item_upload_requirements
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.item_upload_requirements IS 'Which files must or may be uploaded, in which format and size, for a sellable item at ordering time or at a workflow state (D3 §X2). Examples: CBCT (.dcm .nii .npy .vti .zip) and IOS (.stl .ply .obj .drc .zip) up to 1 GB at ordering; iSmile refinement = STL only; milling-only = design STL + construction file; IOS required only if the guide answer is Yes; AoX HTML review up to 100 MB; fab notes PDF up to 20 MB. One row = one upload purpose required or allowed in one scope. The upload itself is a docs.documents row with the same purpose code, linked through docs.document_links. Configuration; evaluated by V100 / the application.';
COMMENT ON COLUMN catalog.item_upload_requirements.id IS 'Surrogate key of the upload requirement; not referenced elsewhere.';
COMMENT ON COLUMN catalog.item_upload_requirements.tenant_id IS 'Owning tenant (core.tenants; FK added by V090). Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.item_upload_requirements.sellable_item_id IS 'The sellable item the requirement applies to. With workflow_state_id also set, the requirement applies to that item at that state only. NULL = applies to every item reaching workflow_state_id.';
COMMENT ON COLUMN catalog.item_upload_requirements.workflow_state_id IS 'Workflow state (workflow.workflow_states; FK added by V090) at which the upload is required, e.g. design review or pre-production. NULL = required at ordering (the upload step of the order form).';
COMMENT ON COLUMN catalog.item_upload_requirements.purpose_code IS 'Document purpose the upload must carry, the same code as docs.documents.purpose (lookup document_purpose: cbct, ios, photos, dsd_photos, facial_scan, photogrammetry, additional, design_stl, construction_file, pre_op, pre_surgery, post_surgery, html_design, stl_design, fab_notes_pdf, preprod_files, ...).';
COMMENT ON COLUMN catalog.item_upload_requirements.is_required IS 'True = the order or state cannot proceed without this upload while the condition holds; false = upload is offered but optional.';
COMMENT ON COLUMN catalog.item_upload_requirements.allowed_extensions IS 'Accepted file name extensions, lower case with the leading dot (e.g. {.stl,.ply,.obj,.zip}). Empty array = any extension accepted.';
COMMENT ON COLUMN catalog.item_upload_requirements.max_size_bytes IS 'Largest accepted file in bytes (1 GB = 1073741824 for most order uploads; 2 GB for Relu and AoX STLs; 100 MB AoX HTML; 20 MB fab notes).';
COMMENT ON COLUMN catalog.item_upload_requirements.max_file_count IS 'How many files of this purpose may be attached in this scope; 1 by default (one file per upload kind, Connect 3.5).';
COMMENT ON COLUMN catalog.item_upload_requirements.condition IS 'When the requirement applies, in the same JSON shape as catalog.item_field_rules.condition (leaf {"field": "<catalog.fields.code>", "op": ..., "value"/"values": ...} or {"attribute": "is_digital", ...}; combinators all / any / not). {} = always applies.';
COMMENT ON COLUMN catalog.item_upload_requirements.sort_order IS 'Display order of upload slots on the upload step, ascending.';
COMMENT ON COLUMN catalog.item_upload_requirements.is_active IS 'False = requirement switched off without deleting it.';
COMMENT ON COLUMN catalog.item_upload_requirements.notes IS 'Source of the requirement (document, user story) or instructions shown to staff. NULL = no note.';
COMMENT ON COLUMN catalog.item_upload_requirements.legacy_id IS 'Source row id when loaded from a legacy source. NULL = created in threeddx3 (seeded or configured).';
COMMENT ON COLUMN catalog.item_upload_requirements.legacy_source IS 'Source of a loaded row, e.g. ''ec2:<path>''. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.item_upload_requirements.legacy_key IS 'Composite source key when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.item_upload_requirements.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.item_upload_requirements.updated_at IS 'UTC instant of the last update, maintained by trg_item_upload_requirements__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.item_upload_requirements.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.item_upload_requirements.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_item_upload_requirements ON catalog.item_upload_requirements IS 'One row per upload requirement.';
COMMENT ON CONSTRAINT ck_item_upload_requirements__scope ON catalog.item_upload_requirements IS 'A requirement is scoped to a sellable item, a workflow state, or both (an item at a state); it never applies to everything.';
COMMENT ON CONSTRAINT ck_item_upload_requirements__max_size_positive ON catalog.item_upload_requirements IS 'The size limit is a positive number of bytes.';
COMMENT ON CONSTRAINT ck_item_upload_requirements__max_file_count_positive ON catalog.item_upload_requirements IS 'At least one file of the purpose can be attached.';
COMMENT ON CONSTRAINT ck_item_upload_requirements__extensions_format ON catalog.item_upload_requirements IS 'Each extension is lower case, starts with a dot and contains only letters and digits (multi-part such as .nii.gz allowed); no NULL entries.';
COMMENT ON CONSTRAINT ck_item_upload_requirements__condition_object ON catalog.item_upload_requirements IS 'A condition is a JSON object ({} = always).';
COMMENT ON CONSTRAINT fk_item_upload_requirements__sellable_item_id ON catalog.item_upload_requirements IS 'Requirements of an item are removed with it (configuration child).';
COMMENT ON INDEX catalog.ix_item_upload_requirements__sellable_item_id IS 'Loads the upload slots of an item for the order form''s upload step; serves the FK check.';
COMMENT ON INDEX catalog.ix_item_upload_requirements__workflow_state_id IS 'Loads the uploads required when an order item reaches a workflow state; serves the FK check from workflow.workflow_states.';
COMMENT ON INDEX catalog.uq_item_upload_requirements__legacy IS 'Every loaded row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_item_upload_requirements__touch_updated_at BEFORE UPDATE ON catalog.item_upload_requirements
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_item_upload_requirements__touch_updated_at ON catalog.item_upload_requirements IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.tooth_chart_components  (v3 new, D3 §12 unified teeth chart)
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.tooth_chart_components (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    sellable_item_id    bigint NOT NULL,
    component_code      core.entity_code NOT NULL,
    label               varchar(100) NOT NULL,
    allowed_site_types  varchar(40)[] NOT NULL,
    sort_order          integer NOT NULL DEFAULT 0,
    is_active           boolean NOT NULL DEFAULT true,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_tooth_chart_components PRIMARY KEY (id),
    CONSTRAINT uq_tooth_chart_components__sellable_item_id__component_code UNIQUE (sellable_item_id, component_code),
    CONSTRAINT uq_tooth_chart_components__sellable_item_id__id UNIQUE (sellable_item_id, id),
    CONSTRAINT ck_tooth_chart_components__allowed_site_types CHECK (
        cardinality(allowed_site_types) >= 1
        AND array_position(allowed_site_types, NULL) IS NULL
        AND allowed_site_types <@ ARRAY['missing', 'extraction', 'to_be_extracted', 'implant', 'abutment',
                                        'crown', 'pontic', 'restoration', 'veneer', 'inlay_onlay']::varchar(40)[]),
    CONSTRAINT fk_tooth_chart_components__sellable_item_id FOREIGN KEY (sellable_item_id)
        REFERENCES catalog.sellable_items (id) ON DELETE CASCADE ON UPDATE NO ACTION
);
CREATE UNIQUE INDEX uq_tooth_chart_components__legacy ON catalog.tooth_chart_components
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.tooth_chart_components IS 'Rows of the unified "Specify Teeth" chart per restorative service (D3 §12, US#1-4): one row = one component (Crown, Abutment, Pontic, Veneers, Inlay/Onlay) that a sellable item offers, shown under both Maxilla and Mandible. Selections are stored as clinical.tooth_sites with one of the allowed site types; per-unit price = configured rate x valid selections per component (pricing.formula_terms quantity sources crown_count, abutment_count, pontic_count, veneer_count, inlay_onlay_count). Which components may share a tooth is in catalog.tooth_chart_component_conflicts. Configuration child of catalog.sellable_items.';
COMMENT ON COLUMN catalog.tooth_chart_components.id IS 'Surrogate key. Referenced by catalog.tooth_chart_component_conflicts.';
COMMENT ON COLUMN catalog.tooth_chart_components.tenant_id IS 'Owning tenant (core.tenants; FK added by V090); always the tenant of the item. Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.tooth_chart_components.sellable_item_id IS 'The restorative service whose teeth chart shows this component row.';
COMMENT ON COLUMN catalog.tooth_chart_components.component_code IS 'Stable code of the component within the service: crown, abutment, pontic, veneer, inlay_onlay (others by configuration).';
COMMENT ON COLUMN catalog.tooth_chart_components.label IS 'Row label shown on the chart (e.g. "Crown", "Inlay/Onlay").';
COMMENT ON COLUMN catalog.tooth_chart_components.allowed_site_types IS 'clinical.tooth_sites.site_type values a selection in this row may be stored as: missing, extraction, to_be_extracted, implant, abutment, crown, pontic, restoration, veneer, inlay_onlay (the v2 clinical.site_type set plus the v3 additions; must stay in step with clinical.tooth_sites).';
COMMENT ON COLUMN catalog.tooth_chart_components.sort_order IS 'Position of the row on the chart, ascending.';
COMMENT ON COLUMN catalog.tooth_chart_components.is_active IS 'False = row no longer offered on new orders; existing selections remain.';
COMMENT ON COLUMN catalog.tooth_chart_components.legacy_id IS 'Source row id when loaded from a legacy source. NULL = created in threeddx3 (seeded or configured).';
COMMENT ON COLUMN catalog.tooth_chart_components.legacy_source IS 'Source of a loaded row, e.g. ''ec2:<path>''. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.tooth_chart_components.legacy_key IS 'Composite source key when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.tooth_chart_components.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.tooth_chart_components.updated_at IS 'UTC instant of the last update, maintained by trg_tooth_chart_components__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.tooth_chart_components.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.tooth_chart_components.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_tooth_chart_components ON catalog.tooth_chart_components IS 'One row per component row of a service''s chart.';
COMMENT ON CONSTRAINT uq_tooth_chart_components__sellable_item_id__component_code ON catalog.tooth_chart_components IS 'A service offers each component at most once.';
COMMENT ON CONSTRAINT uq_tooth_chart_components__sellable_item_id__id ON catalog.tooth_chart_components IS 'Target of the composite FKs from catalog.tooth_chart_component_conflicts, which guarantee both components of a conflict belong to the same service.';
COMMENT ON CONSTRAINT ck_tooth_chart_components__allowed_site_types ON catalog.tooth_chart_components IS 'A component allows at least one site type, and only site types clinical.tooth_sites can store.';
COMMENT ON CONSTRAINT fk_tooth_chart_components__sellable_item_id ON catalog.tooth_chart_components IS 'Component rows belong to the service and are removed with it (configuration child).';
COMMENT ON INDEX catalog.uq_tooth_chart_components__legacy IS 'Every loaded row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_tooth_chart_components__touch_updated_at BEFORE UPDATE ON catalog.tooth_chart_components
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_tooth_chart_components__touch_updated_at ON catalog.tooth_chart_components IS 'Sets updated_at and updated_by_user_id on every update.';

-- -----------------------------------------------------------------------------
-- catalog.tooth_chart_component_conflicts  (v3 new, D3 §12)
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.tooth_chart_component_conflicts (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    sellable_item_id    bigint NOT NULL,
    component_a_id      bigint NOT NULL,
    component_b_id      bigint NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    CONSTRAINT pk_tooth_chart_component_conflicts PRIMARY KEY (id),
    CONSTRAINT ck_tooth_chart_component_conflicts__distinct CHECK (component_a_id <> component_b_id),
    CONSTRAINT fk_tooth_chart_component_conflicts__component_a_id FOREIGN KEY (sellable_item_id, component_a_id)
        REFERENCES catalog.tooth_chart_components (sellable_item_id, id) ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT fk_tooth_chart_component_conflicts__component_b_id FOREIGN KEY (sellable_item_id, component_b_id)
        REFERENCES catalog.tooth_chart_components (sellable_item_id, id) ON DELETE CASCADE ON UPDATE NO ACTION
);
CREATE UNIQUE INDEX uq_tooth_chart_component_conflicts__pair ON catalog.tooth_chart_component_conflicts
    (sellable_item_id, LEAST(component_a_id, component_b_id), GREATEST(component_a_id, component_b_id));
CREATE INDEX ix_tooth_chart_component_conflicts__item__component_a ON catalog.tooth_chart_component_conflicts
    (sellable_item_id, component_a_id);
CREATE INDEX ix_tooth_chart_component_conflicts__item__component_b ON catalog.tooth_chart_component_conflicts
    (sellable_item_id, component_b_id);

COMMENT ON TABLE catalog.tooth_chart_component_conflicts IS 'Pairs of teeth-chart components of one service that cannot be selected on the same tooth (D3 §12): e.g. Pontic conflicts with Crown and with Abutment, while Crown and Abutment may share a tooth (no row). One row = one unordered conflicting pair; the chart disables a conflicting cell live and the server re-validates on submit (V100). Pure link table: inserted and deleted, never updated.';
COMMENT ON COLUMN catalog.tooth_chart_component_conflicts.id IS 'Surrogate key of the conflicting component pair; not referenced elsewhere.';
COMMENT ON COLUMN catalog.tooth_chart_component_conflicts.tenant_id IS 'Owning tenant (core.tenants; FK added by V090); always the tenant of the service. Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.tooth_chart_component_conflicts.sellable_item_id IS 'The service both components belong to (part of both composite FKs, so a conflict cannot pair components of different services).';
COMMENT ON COLUMN catalog.tooth_chart_component_conflicts.component_a_id IS 'One component of the conflicting pair (order within the pair has no meaning).';
COMMENT ON COLUMN catalog.tooth_chart_component_conflicts.component_b_id IS 'The other component of the conflicting pair.';
COMMENT ON COLUMN catalog.tooth_chart_component_conflicts.created_at IS 'UTC instant the conflict was configured. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.tooth_chart_component_conflicts.created_by_user_id IS 'iam.users id of the user who configured the conflict. No FK by design: audit history must survive deletion of the user. NULL = system or seed. [AUDIT]';
COMMENT ON CONSTRAINT pk_tooth_chart_component_conflicts ON catalog.tooth_chart_component_conflicts IS 'One row per conflicting pair.';
COMMENT ON CONSTRAINT ck_tooth_chart_component_conflicts__distinct ON catalog.tooth_chart_component_conflicts IS 'A component cannot conflict with itself.';
COMMENT ON CONSTRAINT fk_tooth_chart_component_conflicts__component_a_id ON catalog.tooth_chart_component_conflicts IS 'Component a exists and belongs to the same service; the conflict is removed with the component (link row).';
COMMENT ON CONSTRAINT fk_tooth_chart_component_conflicts__component_b_id ON catalog.tooth_chart_component_conflicts IS 'Component b exists and belongs to the same service; the conflict is removed with the component (link row).';
COMMENT ON INDEX catalog.uq_tooth_chart_component_conflicts__pair IS 'A pair is recorded once regardless of order: (crown, pontic) and (pontic, crown) are the same conflict.';
COMMENT ON INDEX catalog.ix_tooth_chart_component_conflicts__item__component_a IS 'Finds the conflicts of a component (as a) when validating a chart; serves the composite FK check on component deletion.';
COMMENT ON INDEX catalog.ix_tooth_chart_component_conflicts__item__component_b IS 'Finds the conflicts of a component (as b) when validating a chart; serves the composite FK check on component deletion.';

-- -----------------------------------------------------------------------------
-- catalog.articles  (amended: manufacturer_id, D1)
-- -----------------------------------------------------------------------------
CREATE TABLE catalog.articles (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    article_number      varchar(60) NOT NULL,
    name                varchar(200) NOT NULL,
    article_group       varchar(60),
    manufacturer_id     bigint,
    udi                 varchar(120),
    is_active           boolean NOT NULL DEFAULT true,
    metadata            jsonb NOT NULL DEFAULT '{}'::jsonb,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_articles PRIMARY KEY (id),
    CONSTRAINT uq_articles__uuid UNIQUE (uuid),
    CONSTRAINT uq_articles__tenant_id__article_number UNIQUE (tenant_id, article_number),
    CONSTRAINT ck_articles__metadata_object CHECK (jsonb_typeof(metadata) = 'object')
);
CREATE INDEX ix_articles__manufacturer_id ON catalog.articles (manufacturer_id) WHERE manufacturer_id IS NOT NULL;
CREATE UNIQUE INDEX uq_articles__legacy ON catalog.articles
    (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE catalog.articles IS 'Physical part numbers used by production and shipping: guide sleeves (legacy sleeveArticleNumbers and the sleeve JSON catalogue), fixation pins, surgical-kit parts and box UDIs. One row = one article number of one tenant, optionally tied to its implant manufacturer. Referenced by clinical.guide_sleeves / guide_fixation_pins, production, shipping and pricing.price_list_items.article_id. Retired with is_active = false.';
COMMENT ON COLUMN catalog.articles.id IS 'Surrogate key. Referenced by clinical sleeve/pin/analog tables, production, shipping and pricing.price_list_items.article_id.';
COMMENT ON COLUMN catalog.articles.uuid IS 'Public identifier used by the API instead of the numeric id. System-generated.';
COMMENT ON COLUMN catalog.articles.tenant_id IS 'Owning tenant (core.tenants; FK added by V090). Row-level security isolates rows by this column.';
COMMENT ON COLUMN catalog.articles.article_number IS 'Manufacturer or 3DDX part number as printed on the part (e.g. "525-425-4L"), unique per tenant. Migrated from sleeveArticleNumbers.name / articleNumber.';
COMMENT ON COLUMN catalog.articles.name IS 'Description of the article. Migrated from sleeveArticleNumbers.description; defaults to the article number when legacy has none.';
COMMENT ON COLUMN catalog.articles.article_group IS 'Kind of article: sleeve, pin, kit_part, box (free list, grouped in reports). NULL = not classified.';
COMMENT ON COLUMN catalog.articles.manufacturer_id IS 'Implant / sleeve manufacturer that makes or specifies the article (clinical.implant_manufacturers; FK added by V090). Needed to resolve the sleeve JSON catalogue key (partID, manufacturer). NULL = 3DDX own part or manufacturer unknown.';
COMMENT ON COLUMN catalog.articles.udi IS 'Unique Device Identifier (device identifier part) printed on the label, FDA UDI. NULL = the article carries no UDI (non-device part or not yet assigned).';
COMMENT ON COLUMN catalog.articles.is_active IS 'False = article no longer used for new work; history intact.';
COMMENT ON COLUMN catalog.articles.metadata IS 'Descriptive attributes not filtered or reported on (diameter, length notes from the JSON catalogue). JSON object.';
COMMENT ON COLUMN catalog.articles.legacy_id IS 'Source row id (sleeveArticleNumbers.ID). NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.articles.legacy_source IS 'Source table of the migrated row (''sleeveArticleNumbers''), or ''ec2:<path>'' for the JSON catalogue. NULL = created in threeddx3.';
COMMENT ON COLUMN catalog.articles.legacy_key IS 'Composite source key (e.g. JSON partID + manufacturer) when one legacy id is not enough. NULL = legacy_id alone identifies the source row, or the row was created in threeddx3.';
COMMENT ON COLUMN catalog.articles.created_at IS 'UTC instant the row was inserted. System-generated. [AUDIT]';
COMMENT ON COLUMN catalog.articles.updated_at IS 'UTC instant of the last update, maintained by trg_articles__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN catalog.articles.created_by_user_id IS 'iam.users id of the user who inserted the row. No FK by design: audit history must survive deletion of the user. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN catalog.articles.updated_by_user_id IS 'iam.users id of the user who last updated the row. No FK by design. NULL = never updated by a user (system or migration). [AUDIT]';
COMMENT ON CONSTRAINT pk_articles ON catalog.articles IS 'One row per article.';
COMMENT ON CONSTRAINT uq_articles__uuid ON catalog.articles IS 'The public identifier is unique.';
COMMENT ON CONSTRAINT uq_articles__tenant_id__article_number ON catalog.articles IS 'An article number identifies one article within a tenant; the ETL upserts on (tenant_id, article_number).';
COMMENT ON CONSTRAINT ck_articles__metadata_object ON catalog.articles IS 'metadata is always a JSON object.';
COMMENT ON INDEX catalog.ix_articles__manufacturer_id IS 'Lists the articles of a manufacturer (sleeve selection per implant system) and serves the FK check from clinical.implant_manufacturers.';
COMMENT ON INDEX catalog.uq_articles__legacy IS 'Every migrated row is traceable to one source row and cannot be loaded twice.';

CREATE TRIGGER trg_articles__touch_updated_at BEFORE UPDATE ON catalog.articles
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_articles__touch_updated_at ON catalog.articles IS 'Sets updated_at and updated_by_user_id on every update.';
